import{c as t,Q as o,j as r,m as a}from"./chunks/framework.g_l1frA7.js";const m=JSON.parse('{"title":"Journey","description":"","frontmatter":{},"headers":[],"relativePath":"guide/journey.md","filePath":"guide/journey.md","lastUpdated":null}'),n={name:"guide/journey.md"};function d(s,e,i,l,h,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="journey" tabindex="-1">Journey <a class="header-anchor" href="#journey" aria-label="Permalink to &quot;Journey&quot;">​</a></h1><p>Seven milestones from stability to freedom — where you are, what unlocks next, and the Copilot entry points that get you there.</p><h2 id="the-milestones" tabindex="-1">The milestones <a class="header-anchor" href="#the-milestones" aria-label="Permalink to &quot;The milestones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Milestone</th><th>What it means</th></tr></thead><tbody><tr><td>1</td><td>Stability</td><td>Bills paid, income tracked, categories set</td></tr><tr><td>2</td><td>Emergency buffer</td><td>1 month of expenses saved</td></tr><tr><td>3</td><td>Emergency fund</td><td>3–6 months saved (Ramsey/Sethi)</td></tr><tr><td>4</td><td>Debt free</td><td>Non-mortgage debt cleared, snowball order followed</td></tr><tr><td>5</td><td>On track</td><td>Savings rate ≥10% for several months; allocation healthy</td></tr><tr><td>6</td><td>Compounding</td><td>Goals funded, 10/20/30-year projection is credible</td></tr><tr><td>7</td><td>Freedom</td><td>Investments + cash cover years of expenses; Behaviour &gt; math is the focus</td></tr></tbody></table><p>Progress is computed from <code>wellness_context</code> and goal/budget state. A milestone unlocks when its thresholds are met against your actual ledger — the Copilot will not mark it complete on promises.</p><h2 id="using-journey" tabindex="-1">Using Journey <a class="header-anchor" href="#using-journey" aria-label="Permalink to &quot;Using Journey&quot;">​</a></h2><ul><li>Click a milestone → Copilot opens with a grounded prompt (“How do I reach Emergency Fund with my current burn rate?”).</li><li>The progress bar animates on reveal (respects <code>prefers-reduced-motion</code>).</li><li>“More” disclosure holds secondary detail — primary milestones stay scannable.</li></ul><p>Journey is a motivator, not a scoreboard. The underlying math is exposed in the metric inspector whenever you want to check it.</p><p>See also: <a href="/FinSight/framework/overview">Financial Framework</a>, <a href="/FinSight/guide/goals">Goals</a>.</p>',9)])])}const p=t(n,[["render",d]]);export{m as __pageData,p as default};
